  textStyle?: TextStyle;
}

export interface TextStyle {
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  strikethrough?: boolean;
  fontSize?: Dimension;
  foregroundColor?: Color;
  backgroundColor?: Color;
  fontFamily?: string;
  link?: Link;
}

export interface Link {
  url?: string;
  bookmarkId?: string;
  headingId?: string;
}

export interface Dimension {
  magnitude: number;
  unit: string;
}

export interface Color {
  rgbColor?: RgbColor;
}

export interface RgbColor {
