  inputSchema: defineSchema((v) =>
    v.object({
      query: v
        .string()
        .describe(
          "Search query using Drive query syntax. Examples: \"name contains 'report'\", \"mimeType='application/pdf'\", \"fullText contains 'budget'\"",
        ),
      pageSize: v
        .number()
        .min(1)
        .max(1000)
        .default(100)
        .describe("Maximum number of files to return"),
      pageToken: v
        .string()
        .optional()
        .describe("Token for pagination to get next page of results"),
      orderBy: v
        .enum([
          "createdTime",
          "folder",
          "modifiedByMeTime",
          "modifiedTime",
          "name",
          "quotaBytesUsed",
          "recency",
          "sharedWithMeTime",
          "starred",
          "viewedByMeTime",
        ])
        .optional()
        .describe("Field to sort results by"),
    })
  )(),
  async execute({ query, pageSize, pageToken, orderBy }, context) {
    const userId = requireUserIdFromContext(context);
    const client = createDriveClient(userId);

    const result = await client.searchFiles({
      query,
      pageSize,
      pageToken,
      orderBy: orderBy ? `${orderBy} desc` : undefined,
    });

    const files = result.files.map((file) => ({
      id: file.id,
      name: file.name,
      mimeType: file.mimeType,
      isFolder: file.mimeType === FOLDER_MIME_TYPE,
      size: file.size,
      createdTime: file.createdTime,
      modifiedTime: file.modifiedTime,
      webViewLink: file.webViewLink,
      iconLink: file.iconLink,
      thumbnailLink: file.thumbnailLink,
      starred: file.starred,
      shared: file.shared,
      parents: file.parents,
    }));

    const nextPageToken = result.nextPageToken;

    return {
      files,
      nextPageToken,
      hasMore: Boolean(nextPageToken),
      incompleteSearch: result.incompleteSearch,
    };
  },
});

