import { tool } from "veryfront/tool";
import { defineSchema } from "veryfront/schemas";
import {
  formatMergeRequestForDisplay,
  listMergeRequests,
} from "../lib/gitlab-client.ts";
import { requireUserIdFromContext } from "../lib/user-id.ts";

export default tool({
  id: "gitlab-list-merge-requests",
  description:
    "List merge requests in GitLab. Can filter by scope, state, labels, and specific project. Returns MR titles, states, branches, assignees, and reviewers.",
  inputSchema: defineSchema((v) =>
    v.object({
      scope: v
        .enum(["created_by_me", "assigned_to_me", "all"])
        .default("all")
        .describe("Scope of merge requests to list"),
      state: v
        .enum(["opened", "closed", "merged", "all"])
        .default("opened")
        .describe("State of merge requests to list"),
      labels: v
        .array(v.string())
        .optional()
        .describe('Filter by labels (e.g., ["feature", "review-needed"])'),
      projectId: v
        .union([v.number(), v.string()])
        .optional()
        .describe('Project ID or path (e.g., "gitlab-org/gitlab" or 278964)'),
      limit: v.number().min(1).max(100).default(20).describe(
        "Maximum number of results to return",
      ),
    })
  )(),
  async execute({ scope, state, labels, projectId, limit }, context) {
    const userId = requireUserIdFromContext(context);
    const mergeRequests = await listMergeRequests(userId, {
      scope,
      state,
      labels,
      projectId,
      perPage: limit,
    });

    if (mergeRequests.length === 0) {
      return {
        message: "No merge requests found matching the criteria.",
        count: 0,
        mergeRequests: [],
      };
    }

    return {
      count: mergeRequests.length,
      mergeRequests: mergeRequests.map((mr) => {
        const description = mr.description ?? "";
        const truncatedDescription = description.length > 200
          ? `${description.substring(0, 200)}...`
          : description;

        return {
          id: mr.id,
          iid: mr.iid,
          projectId: mr.project_id,
          title: mr.title,
          state: mr.state,
          draft: mr.draft,
          sourceBranch: mr.source_branch,
          targetBranch: mr.target_branch,
          labels: mr.labels,
          author: {
            username: mr.author.username,
            name: mr.author.name,
          },
          assignees: mr.assignees.map((a) => ({
            username: a.username,
            name: a.name,
          })),
          reviewers: mr.reviewers.map((r) => ({
            username: r.username,
            name: r.name,
          })),
          createdAt: mr.created_at,
          updatedAt: mr.updated_at,
          mergedAt: mr.merged_at,
          webUrl: mr.web_url,
          description: truncatedDescription,
        };
      }),
      summary: mergeRequests.map(formatMergeRequestForDisplay).join("\n\n"),
    };
  },
});

