import { linearConfig, OAuthService } from "veryfront/oauth";
import { tokenStore } from "./token-store.ts";

// OAuthService refreshes expired tokens under the store's refresh lock.
const linearService = new OAuthService(linearConfig, tokenStore);

const LINEAR_API_URL = "https://api.linear.app/graphql";

export interface LinearIssue {
  id: string;
  identifier: string;
  title: string;
  description?: string;
  priority: number;
  priorityLabel: string;
  state: {
    id: string;
    name: string;
    type: string;
  };
  assignee?: {
    id: string;
    name: string;
    email: string;
  };
  team: {
    id: string;
    name: string;
    key: string;
  };
  project?: {
    id: string;
    name: string;
  };
  labels: {
    nodes: Array<{
      id: string;
      name: string;
      color: string;
    }>;
  };
  createdAt: string;
  updatedAt: string;
  url: string;
}

export interface LinearProject {
  id: string;
  name: string;
  description?: string;
  state: string;
  progress: number;
  url: string;
  lead?: {
    id: string;
    name: string;
  };
  teams: {
    nodes: Array<{
      id: string;
      name: string;
      key: string;
    }>;
  };
  createdAt: string;
  updatedAt: string;
}

export interface LinearTeam {
  id: string;
  name: string;
  key: string;
}

export interface LinearWorkflowState {
  id: string;
  name: string;
  type: string;
}

export interface LinearUser {
  id: string;
  name: string;
  displayName?: string;
  email: string;
  active: boolean;
  avatarUrl?: string;
}

export interface LinearComment {
  id: string;
  body: string;
  createdAt: string;
  user?: {
    id: string;
    name: string;
  };
  issue?: {
    id: string;
    identifier: string;
    title: string;
  };
}

interface GraphQLResponse<T> {
  data?: T;
  errors?: Array<{
    message: string;
    path?: string[];
  }>;
}

async function linearFetch<T>(
  userId: string,
  query: string,
  variables?: Record<string, unknown>,
): Promise<T> {
  const token = await linearService.getAccessToken(userId);
  if (!token) {
    throw new Error("Not authenticated with Linear. Please connect your account.");
  }

  const response = await fetch(LINEAR_API_URL, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ query, variables }),
  });

  if (!response.ok) {
    throw new Error(`Linear API error: ${response.status} ${response.statusText}`);
  }

  const json: GraphQLResponse<T> = await response.json();

  const errorMessage = json.errors?.[0]?.message;
  if (errorMessage) {
    throw new Error(`Linear GraphQL error: ${errorMessage}`);
  }

  if (!json.data) {
    throw new Error("Linear API returned no data");
  }

  return json.data;
}

export async function searchIssues(
  userId: string,
  query: string,
  options?: {
    limit?: number;
    includeArchived?: boolean;
  },
): Promise<LinearIssue[]> {
  const gqlQuery = `
    query SearchIssues($query: String!, $first: Int, $includeArchived: Boolean) {
      issueSearch(query: $query, first: $first, includeArchived: $includeArchived) {
        nodes {
          id
          identifier
          title
          description
          priority
          priorityLabel
          state {
            id
            name
            type
          }
          assignee {
            id
            name
            email
          }
          team {
            id
            name
            key
          }
          project {
            id
            name
          }
          labels {
            nodes {
              id
              name
              color
            }
          }
          createdAt
          updatedAt
          url
        }
      }
    }
  `;

  const data = await linearFetch<{ issueSearch: { nodes: LinearIssue[] } }>(userId, gqlQuery, {
    query,
    first: options?.limit ?? 10,
    includeArchived: options?.includeArchived ?? false,
  });

  return data.issueSearch.nodes;
}

export async function getIssue(userId: string, issueId: string): Promise<LinearIssue> {
  const query = `
    query GetIssue($id: String!) {
      issue(id: $id) {
        id
        identifier
        title
        description
        priority
        priorityLabel
        state {
          id
          name
          type
        }
        assignee {
          id
          name
          email
        }
        team {
          id
          name
          key
        }
        project {
          id
          name
        }
        labels {
          nodes {
            id
            name
            color
          }
        }
        createdAt
        updatedAt
        url
      }
    }
  `;

  const data = await linearFetch<{ issue: LinearIssue }>(userId, query, { id: issueId });
  return data.issue;
}

export async function createIssue(userId: string, options: {
  teamId: string;
  title: string;
  description?: string;
  priority?: number;
  stateId?: string;
  assigneeId?: string;
  projectId?: string;
  labelIds?: string[];
}): Promise<LinearIssue> {
  const mutation = `
    mutation CreateIssue($input: IssueCreateInput!) {
      issueCreate(input: $input) {
        success
        issue {
          id
          identifier
          title
          description
          priority
          priorityLabel
          state {
            id
            name
            type
          }
          assignee {
            id
            name
            email
          }
          team {
            id
            name
            key
          }
          project {
            id
            name
          }
          labels {
            nodes {
              id
              name
              color
            }
          }
          createdAt
          updatedAt
          url
        }
      }
    }
  `;

  const input: Record<string, unknown> = {
    teamId: options.teamId,
    title: options.title,
  };

  if (options.description) input.description = options.description;
  if (options.priority !== undefined) input.priority = options.priority;
  if (options.stateId) input.stateId = options.stateId;
  if (options.assigneeId) input.assigneeId = options.assigneeId;
  if (options.projectId) input.projectId = options.projectId;
  if (options.labelIds?.length) input.labelIds = options.labelIds;

  const data = await linearFetch<{ issueCreate: { success: boolean; issue: LinearIssue } }>(
    userId,
    mutation,
    {
      input,
    },
  );

  if (!data.issueCreate.success) {
    throw new Error("Failed to create issue");
  }

  return data.issueCreate.issue;
}

export async function updateIssue(
  userId: string,
  issueId: string,
  options: {
    title?: string;
    description?: string;
    priority?: number;
    stateId?: string;
    assigneeId?: string;
    projectId?: string;
    labelIds?: string[];
  },
): Promise<LinearIssue> {
  const mutation = `
    mutation UpdateIssue($id: String!, $input: IssueUpdateInput!) {
      issueUpdate(id: $id, input: $input) {
        success
        issue {
          id
          identifier
          title
          description
          priority
          priorityLabel
          state {
            id
            name
            type
          }
          assignee {
            id
            name
            email
          }
          team {
            id
            name
            key
          }
          project {
            id
            name
            }
          labels {
            nodes {
              id
              name
              color
            }
          }
          createdAt
          updatedAt
          url
        }
      }
    }
  `;

  const input: Record<string, unknown> = {};

  if (options.title) input.title = options.title;
  if (options.description !== undefined) input.description = options.description;
  if (options.priority !== undefined) input.priority = options.priority;
  if (options.stateId) input.stateId = options.stateId;
  if (options.assigneeId) input.assigneeId = options.assigneeId;
  if (options.projectId) input.projectId = options.projectId;
  if (options.labelIds) input.labelIds = options.labelIds;

  const data = await linearFetch<{ issueUpdate: { success: boolean; issue: LinearIssue } }>(
    userId,
    mutation,
    {
      id: issueId,
      input,
    },
  );

  if (!data.issueUpdate.success) {
    throw new Error("Failed to update issue");
  }

  return data.issueUpdate.issue;
}

export async function listProjects(userId: string, options?: {
  limit?: number;
  includeArchived?: boolean;
}): Promise<LinearProject[]> {
  const query = `
    query ListProjects($first: Int, $includeArchived: Boolean) {
      projects(first: $first, includeArchived: $includeArchived) {
        nodes {
          id
          name
          description
          state
          progress
          url
          lead {
            id
            name
          }
          teams {
            nodes {
              id
              name
              key
            }
          }
          createdAt
          updatedAt
        }
      }
    }
  `;

  const data = await linearFetch<{ projects: { nodes: LinearProject[] } }>(userId, query, {
    first: options?.limit ?? 20,
    includeArchived: options?.includeArchived ?? false,
  });

  return data.projects.nodes;
}

export async function getTeams(userId: string): Promise<LinearTeam[]> {
  const query = `
    query GetTeams {
      teams {
        nodes {
          id
          name
          key
        }
      }
    }
  `;

  const data = await linearFetch<{ teams: { nodes: LinearTeam[] } }>(userId, query);
  return data.teams.nodes;
}

export async function getWorkflowStates(
  userId: string,
  teamId: string,
): Promise<LinearWorkflowState[]> {
  const query = `
    query GetWorkflowStates($teamId: String!) {
      team(id: $teamId) {
