async function getDbClient(): Promise<Client> {
  const databaseUrl = getDatabaseUrl();
  if (!databaseUrl) {
    throw new Error(
      "DATABASE_URL not configured. Please set DATABASE_URL environment variable.",
    );
  }

  const client = new Client({
    connectionString: databaseUrl,
    ssl: { rejectUnauthorized: false },
  });

  await client.connect();
  return client;
}

export async function query<T = Record<string, unknown>>(
  sql: string,
  params?: unknown[],
): Promise<{ rows: T[]; rowCount: number }> {
  const client = await getDbClient();

  try {
    const result = await client.query(sql, params);
    return { rows: result.rows as T[], rowCount: result.rowCount ?? 0 };
  } finally {
    await client.end();
  }
}

export async function listTables(schema: string = "public"): Promise<TableInfo[]> {
  const result = await query<TableInfo>(
    `SELECT tablename, schemaname, tableowner
     FROM pg_tables
     WHERE schemaname = $1
     ORDER BY tablename`,
    [schema],
  );

  return result.rows;
}

export async function describeTable(
  tableName: string,
  schema: string = "public",
): Promise<{ tableName: string; schema: string; columns: ColumnInfo[] }> {
  const result = await query<ColumnInfo>(
    `SELECT
      column_name,
      data_type,
      is_nullable,
      column_default,
      character_maximum_length
    FROM information_schema.columns
    WHERE table_schema = $1 AND table_name = $2
    ORDER BY ordinal_position`,
    [schema, tableName],
  );

  return { tableName, schema, columns: result.rows };
}

export async function getTableRowCount(
  tableName: string,
  schema: string = "public",
): Promise<number> {
  if (!/^[a-zA-Z0-9_]+$/.test(schema)) {
    throw new Error('Invalid schema name: must contain only letters, numbers, and underscores');
  }
  if (!/^[a-zA-Z0-9_]+$/.test(tableName)) {
    throw new Error('Invalid table name: must contain only letters, numbers, and underscores');
  }
  const result = await query<{ count: string }>(
    `SELECT COUNT(*) as count FROM "${schema}"."${tableName}"`,
  );

  return parseInt(result.rows[0]?.count ?? "0", 10);
}

