      .describe("Type of objects to search for"),
    limit: v
      .number()
      .min(1)
      .max(20)
      .default(10)
      .describe("Maximum number of results to return"),
  }))(),
  async execute({ query, type, limit }, context) {
    const userId = requireUserIdFromContext(context);
    const filter = type === "all" ? undefined : { property: "object", value: type };
    const results = await searchNotion(userId, query, { filter, pageSize: limit });

    return results.map((item) => {
      if (item.object === "page") {
        return {
          id: item.id,
          type: "page",
          title: getPageTitle(item),
          url: item.url,
          lastEdited: item.last_edited_time,
        };
      }

      return {
        id: item.id,
        type: "database",
        title: item.title?.map((t) => t.plain_text).join("") ?? "",
        url: item.url,
      };
    });
  },
});

