import { tool } from "veryfront/tool";
import { defineSchema } from "veryfront/schemas";
import { listAccounts } from "../lib/salesforce-client.ts";
import { requireUserIdFromContext } from "../lib/user-id.ts";

export default tool({
  id: "salesforce-list-accounts",
  description:
    "List accounts from your Salesforce CRM. Returns account information including name, type, industry, website, and billing details.",
  inputSchema: defineSchema((v) => v.object({
    limit: v
      .number()
      .min(1)
      .max(100)
      .default(10)
      .describe("Maximum number of accounts to return"),
    offset: v
      .number()
      .min(0)
      .default(0)
      .describe("Number of records to skip for pagination"),
    fields: v
      .array(v.string())
      .optional()
      .describe(
        "Additional fields to retrieve (e.g., Description, Owner.Name, ParentId)",
      ),
  }))(),
  async execute({ limit, offset, fields }, context) {
    const userId = requireUserIdFromContext(context);
    const response = await listAccounts(userId, { limit, offset, fields });

    return {
      accounts: response.records.map((account) => {
        if (!fields?.length) {
          return {
            id: account.Id,
            name: account.Name,
            type: account.Type,
            industry: account.Industry,
            website: account.Website,
            phone: account.Phone,
            billingCity: account.BillingCity,
            billingState: account.BillingState,
            billingCountry: account.BillingCountry,
            numberOfEmployees: account.NumberOfEmployees,
            annualRevenue: account.AnnualRevenue,
            createdDate: account.CreatedDate,
            lastModifiedDate: account.LastModifiedDate,
            additionalFields: undefined,
          };
        }

        const additionalFields = Object.fromEntries(
          fields
            .filter((field) => account[field] !== undefined)
            .map((field) => [field, account[field]]),
        );

        return {
          id: account.Id,
          name: account.Name,
          type: account.Type,
          industry: account.Industry,
          website: account.Website,
          phone: account.Phone,
          billingCity: account.BillingCity,
          billingState: account.BillingState,
          billingCountry: account.BillingCountry,
          numberOfEmployees: account.NumberOfEmployees,
          annualRevenue: account.AnnualRevenue,
          createdDate: account.CreatedDate,
          lastModifiedDate: account.LastModifiedDate,
          additionalFields,
        };
      }),
      totalSize: response.totalSize,
      hasMore: !response.done,
    };
  },
});

