      .describe("The name of the schema to list tables from. Defaults to PUBLIC."),
    includeDetails: v
      .boolean()
      .default(true)
      .describe(
        "Include detailed information like creation date, row count, size, and owner",
      ),
  }))(),
  async execute({ database, schema, includeDetails }) {
    const tables = await listTables(database, schema);

    const base = { database, schema, count: tables.length };

    if (!includeDetails) {
      return { ...base, tables: tables.map((t) => t.name) };
    }

    return {
      ...base,
      tables: tables.map((t) => ({
        name: t.name,
        databaseName: t.database_name,
        schemaName: t.schema_name,
        kind: t.kind,
        createdOn: t.created_on,
        rowCount: t.row_count ?? null,
        bytes: t.bytes ?? null,
        owner: t.owner,
        comment: t.comment ?? null,
      })),
    };
  },
});

