import { trelloConfig } from "veryfront/oauth";
import { getValidToken, providerFromConfig } from "./oauth.ts";

// The generic OAuthService does not support Trello, so tokens resolve through
// the base scaffold's getValidToken().
const trelloOAuthProvider = providerFromConfig(trelloConfig);

const TRELLO_BASE_URL = "https://api.trello.com/1";

interface TrelloBoard {
  id: string;
  name: string;
  desc: string;
  closed: boolean;
  url: string;
  prefs: {
    background: string;
    backgroundColor: string;
  };
  dateLastActivity: string;
}

interface TrelloList {
  id: string;
  name: string;
  closed: boolean;
  idBoard: string;
  pos: number;
}

interface TrelloCard {
  id: string;
  name: string;
  desc: string;
  closed: boolean;
  idBoard: string;
  idList: string;
  idMembers: string[];
  labels: Array<{
    id: string;
    name: string;
    color: string;
  }>;
  due: string | null;
  dueComplete: boolean;
  url: string;
  dateLastActivity: string;
}

interface TrelloMember {
  id: string;
  fullName: string;
  username: string;
  avatarUrl: string;
}

async function trelloFetch<T>(
  userId: string,
  endpoint: string,
  options: RequestInit = {},
): Promise<T> {
  const token = await getValidToken(trelloOAuthProvider, userId, "trello");
  if (!token) {
    throw new Error("Not authenticated with Trello. Please connect your account.");
  }

  const clientId = process.env.TRELLO_CLIENT_ID;
  if (!clientId) {
    throw new Error("TRELLO_CLIENT_ID environment variable is not set.");
  }

  const url = new URL(`${TRELLO_BASE_URL}${endpoint}`);
  // SECURITY: Trello's REST API requires key and token as query parameters.
  // Tokens in query params may be recorded in browser history, server/proxy
  // access logs, and leaked via the Referer header. The Referrer-Policy
  // header (set by Veryfront's security middleware) mitigates the Referer leak.
  // This is an API design limitation. There is no Authorization header alternative.
  url.searchParams.set("key", clientId);
  url.searchParams.set("token", token);

  const response = await fetch(url.toString(), {
    ...options,
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      ...options.headers,
    },
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => "");
    const message = errorText || response.statusText;
    throw new Error(`Trello API error: ${response.status} ${message}`);
  }

  return response.json();
}

export async function listBoards(userId: string): Promise<TrelloBoard[]> {
  return trelloFetch<TrelloBoard[]>(
    userId,
    "/members/me/boards?fields=name,desc,closed,url,prefs,dateLastActivity",
  );
}

export async function getBoard(userId: string, boardId: string): Promise<TrelloBoard> {
  return trelloFetch<TrelloBoard>(
    userId,
    `/boards/${boardId}?fields=name,desc,closed,url,prefs,dateLastActivity`,
  );
}

export async function listLists(userId: string, boardId: string): Promise<TrelloList[]> {
  return trelloFetch<TrelloList[]>(
    userId,
    `/boards/${boardId}/lists?fields=name,closed,idBoard,pos`,
  );
}

export async function listCards(userId: string, options: {
  boardId?: string;
  listId?: string;
  limit?: number;
}): Promise<TrelloCard[]> {
  const { boardId, listId, limit = 50 } = options;

  const fields =
    "name,desc,closed,idBoard,idList,idMembers,labels,due,dueComplete,url,dateLastActivity";

  if (listId) {
    return trelloFetch<TrelloCard[]>(
      userId,
      `/lists/${listId}/cards?fields=${fields}&limit=${limit}`,
    );
  }

  if (boardId) {
    return trelloFetch<TrelloCard[]>(
      userId,
      `/boards/${boardId}/cards?fields=${fields}&limit=${limit}`,
    );
  }

  throw new Error("Either boardId or listId must be provided");
}

export async function getCard(userId: string, cardId: string): Promise<TrelloCard> {
  return trelloFetch<TrelloCard>(
    userId,
    "/cards/" +
      `${cardId}?fields=name,desc,closed,idBoard,idList,idMembers,labels,due,dueComplete,url,dateLastActivity`,
  );
}

export async function createCard(userId: string, options: {
  listId: string;
  name: string;
  desc?: string;
  due?: string;
  pos?: string | number;
  idMembers?: string[];
  idLabels?: string[];
}): Promise<TrelloCard> {
  const params = new URLSearchParams({
    idList: options.listId,
    name: options.name,
  });

  if (options.desc) params.set("desc", options.desc);
  if (options.due) params.set("due", options.due);
  if (options.pos !== undefined) params.set("pos", String(options.pos));
  if (options.idMembers) params.set("idMembers", options.idMembers.join(","));
  if (options.idLabels) params.set("idLabels", options.idLabels.join(","));

  return trelloFetch<TrelloCard>(userId, `/cards?${params}`, { method: "POST" });
}

export async function updateCard(
  userId: string,
  cardId: string,
  updates: {
    name?: string;
    desc?: string;
    closed?: boolean;
    idList?: string;
    due?: string | null;
    dueComplete?: boolean;
    idMembers?: string[];
    idLabels?: string[];
    pos?: string | number;
  },
): Promise<TrelloCard> {
  const params = new URLSearchParams();

  if (updates.name !== undefined) params.set("name", updates.name);
  if (updates.desc !== undefined) params.set("desc", updates.desc);
  if (updates.closed !== undefined) params.set("closed", String(updates.closed));
  if (updates.idList !== undefined) params.set("idList", updates.idList);
  if (updates.due !== undefined) params.set("due", updates.due ?? "");
  if (updates.dueComplete !== undefined) params.set("dueComplete", String(updates.dueComplete));
  if (updates.idMembers !== undefined) params.set("idMembers", updates.idMembers.join(","));
  if (updates.idLabels !== undefined) params.set("idLabels", updates.idLabels.join(","));
  if (updates.pos !== undefined) params.set("pos", String(updates.pos));

  return trelloFetch<TrelloCard>(userId, `/cards/${cardId}?${params}`, { method: "PUT" });
}

export async function getMe(userId: string): Promise<TrelloMember> {
  return trelloFetch<TrelloMember>(userId, "/members/me?fields=fullName,username,avatarUrl");
}

