{
  "name": "figma",
  "displayName": "Figma",
  "icon": "figma.svg",
  "description": "Access Figma designs, files, comments, and collaborate on design projects",
  "category": "productivity",
  "auth": {
    "type": "oauth2",
    "provider": "figma",
    "authorizationUrl": "https://www.figma.com/oauth",
    "tokenUrl": "https://api.figma.com/v1/oauth/token",
    "scopes": [
      "current_user:read",
      "file_content:read",
      "file_comments:read",
      "file_comments:write"
    ],
    "callbackPath": "/api/auth/figma/callback",
    "tokenAuthMethod": "client_secret_basic",
    "requiredApis": [
      {
        "name": "Figma OAuth App",
        "enableUrl": "https://www.figma.com/developers/apps"
      }
    ]
  },
  "envVars": [
    {
      "name": "FIGMA_CLIENT_ID",
      "description": "Figma OAuth Client ID (from your app settings)",
      "required": true,
      "sensitive": false,
      "docsUrl": "https://www.figma.com/developers/apps"
    },
    {
      "name": "FIGMA_CLIENT_SECRET",
      "description": "Figma OAuth Client Secret",
      "required": true,
      "sensitive": true,
      "docsUrl": "https://www.figma.com/developers/apps"
    }
  ],
  "setupGuide": {
    "title": "Figma setup",
    "steps": [
      {
        "step": 1,
        "title": "Choose who owns the Figma OAuth app",
        "description": "On hosted Veryfront, Figma uses the Veryfront-managed Figma OAuth app: connect Figma from the project's integrations and approve the Figma consent screen, no environment variables needed. Set FIGMA_CLIENT_ID and FIGMA_CLIENT_SECRET only to use your own Figma OAuth app, which is required for local and self-hosted runs."
      },
      {
        "step": 2,
        "title": "Create an OAuth app",
        "description": "In Figma, open My Apps and create a new app for your team or organization.",
        "url": "https://www.figma.com/developers/apps"
      },
      {
        "step": 3,
        "title": "Set the redirect URLs and scopes",
        "description": "Select the scopes current_user:read, file_content:read, file_comments:read and file_comments:write. Add the redirect URI of the environment that completes the flow: https://api.veryfront.com/oauth/callback/figma for hosted Veryfront, or your app origin followed by /api/auth/figma/callback for a local or self-hosted app. Set FIGMA_CLIENT_ID and FIGMA_CLIENT_SECRET from the app's credentials."
      },
      {
        "step": 4,
        "title": "Publish the app",
        "description": "While the app is a draft, only you and your plan admins can authorize it. Publish it privately for your team or organization, or publicly after Figma's review, so other users can connect."
      },
      {
        "step": 5,
        "title": "Verify access",
        "description": "Run Get Me (read-only). It returns the connected Figma user without changing anything."
      }
    ],
    "notes": [
      "The connection requests current_user:read, file_content:read, file_comments:read and file_comments:write. file_comments:write is only needed by the tool that posts comments.",
      "Tools that create, update, send or delete data are marked as writes and need write authority; the other tools are read-only."
    ],
    "documentation": "https://developers.figma.com/docs/rest-api/oauth-apps/"
  },
  "tools": [
    {
      "id": "figma__get_me",
      "name": "Get Me",
      "description": "Get the authenticated user's Figma profile (id, email, handle). Use this to verify the connection and identify the user.",
      "requiresWrite": false,
      "endpoint": {
        "method": "GET",
        "url": "https://api.figma.com/v1/me"
      }
    },
    {
      "id": "figma__get_file",
      "name": "Get File",
      "description": "Get detailed information about a Figma file, including pages, frames, components, and styles. Requires a Figma file key from a file or design URL.",
      "requiresWrite": false,
      "endpoint": {
        "method": "GET",
        "url": "https://api.figma.com/v1/files/{fileKey}",
        "params": {
          "fileKey": {
            "type": "string",
            "in": "path",
            "description": "Figma file key",
            "required": true
          },
          "ids": {
            "type": "string",
            "in": "query",
            "description": "Comma-separated node IDs to include"
          },
          "depth": {
            "type": "number",
            "in": "query",
            "description": "Traversal depth for document tree"
          },
          "geometry": {
            "type": "string",
            "in": "query",
            "description": "Set to paths to export vector data"
          },
          "plugin_data": {
            "type": "string",
            "in": "query",
            "description": "Plugin data namespace to include"
          }
        }
      }
    },
    {
      "id": "figma__get_comments",
      "name": "Get Comments",
      "description": "Get all comments on a Figma file",
      "requiresWrite": false,
      "endpoint": {
        "method": "GET",
        "url": "https://api.figma.com/v1/files/{fileKey}/comments",
        "params": {
          "fileKey": {
            "type": "string",
            "in": "path",
            "description": "Figma file key",
            "required": true
          }
        },
        "response": {
          "transform": "comments"
        }
      }
    },
    {
      "id": "figma__post_comment",
      "name": "Post Comment",
      "description": "Post a comment on a Figma file",
      "requiresWrite": true,
      "endpoint": {
        "method": "POST",
        "url": "https://api.figma.com/v1/files/{fileKey}/comments",
        "params": {
          "fileKey": {
            "type": "string",
            "in": "path",
            "description": "Figma file key",
            "required": true
          }
        },
        "body": {
          "message": {
            "type": "string",
            "description": "Comment text",
            "required": true
          },
          "client_meta": {
            "type": "object",
            "description": "Optional Figma comment position metadata"
          }
        }
      }
    }
  ],
  "prompts": [
    {
      "id": "review_design",
      "title": "Review a design",
      "prompt": "Review a Figma design file and provide feedback on the components, layout, and design system usage.",
      "category": "design",
      "icon": "eye"
    },
    {
      "id": "summarize_comments",
      "title": "Summarize comments",
      "prompt": "Read all comments on a Figma file and summarize the feedback, action items, and unresolved discussions.",
      "category": "design",
      "icon": "message"
    },
    {
      "id": "extract_components",
      "title": "Extract components",
      "prompt": "List all components in a Figma file and describe their structure, variants, and properties.",
      "category": "design",
      "icon": "component"
    },
    {
      "id": "design_feedback",
      "title": "Give design feedback",
      "prompt": "Review the design file and post constructive feedback as comments on specific elements.",
      "category": "design",
      "icon": "plus"
    }
  ],
  "suggestedWith": [
    "linear",
    "slack",
    "notion"
  ]
}

{
  "name": "github",
  "displayName": "GitHub",
  "icon": "github.svg",
  "description": "Manage repositories, issues, and pull requests",
  "category": "development",
  "auth": {
    "type": "oauth2",
    "provider": "github",
    "authorizationUrl": "https://github.com/login/oauth/authorize",
    "tokenUrl": "https://github.com/login/oauth/access_token",
    "scopes": [
      "repo",
      "read:user",
      "read:org"
    ],
    "callbackPath": "/api/auth/github/callback"
  },
  "envVars": [
    {
      "name": "GITHUB_CLIENT_ID",
      "description": "GitHub OAuth App Client ID",
      "required": true,
      "sensitive": false,
      "docsUrl": "https://github.com/settings/developers"
    },
    {
      "name": "GITHUB_CLIENT_SECRET",
      "description": "GitHub OAuth App Client Secret",
      "required": true,
      "sensitive": true,
      "docsUrl": "https://github.com/settings/developers"
    }
  ],
  "setupGuide": {
    "title": "GitHub setup",
    "steps": [
      {
        "step": 1,
        "title": "Choose who owns the GitHub OAuth app",
        "description": "On hosted Veryfront, GitHub uses the Veryfront-managed GitHub OAuth app: connect GitHub from the project's integrations and approve the GitHub consent screen, no environment variables needed. Set GITHUB_CLIENT_ID and GITHUB_CLIENT_SECRET only to use your own GitHub OAuth app, which is required for local and self-hosted runs."
      },
      {
        "step": 2,
        "title": "Create an OAuth App",
        "description": "In GitHub Developer settings, create an OAuth App.",
        "url": "https://github.com/settings/developers"
      },
      {
        "step": 3,
        "title": "Set the callback URL",
        "description": "An OAuth App has one authorization callback URL, so create one app per environment. Add the redirect URI of the environment that completes the flow: https://api.veryfront.com/oauth/callback/github for hosted Veryfront, or your app origin followed by /api/auth/github/callback for a local or self-hosted app. Set GITHUB_CLIENT_ID and GITHUB_CLIENT_SECRET from the app's credentials."
      },
      {
        "step": 4,
        "title": "Verify access",
        "description": "Run Get Current User (read-only). It returns the connected GitHub user without changing anything."
      }
    ],
    "notes": [
      "The connection requests repo, read:user and read:org. repo grants read and write access to the user's public and private repositories.",
      "Organizations that restrict third-party OAuth apps must approve the app before its tools can reach their repositories.",
      "Tools that create, update, send or delete data are marked as writes and need write authority; the other tools are read-only."
    ],
    "documentation": "https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/creating-an-oauth-app"
  },
  "tools": [
    {
      "id": "github__get_current_user",
      "name": "Get Current User",
      "description": "Get the authenticated GitHub user identity",
      "requiresWrite": false,
      "endpoint": {
        "method": "GET",
        "url": "https://api.github.com/user"
      }
    },
    {
      "id": "github__list_repos",
      "name": "List Repositories",
      "description": "Get list of user's repositories",
      "requiresWrite": false,
      "endpoint": {
        "method": "GET",
        "url": "https://api.github.com/user/repos",
        "params": {
          "type": {
            "type": "string",
            "in": "query",
            "description": "Type: all, owner, public, private, member"
          },
          "sort": {
            "type": "string",
            "in": "query",
            "description": "Sort: created, updated, pushed, full_name",
            "default": "updated"
          },
          "per_page": {
            "type": "number",
            "in": "query",
            "description": "Results per page (max 100)",
            "default": 30
          },
          "page": {
            "type": "number",
            "in": "query",
            "description": "Page number for pagination"
          }
        },
        "response": {
          "historicalSummary": {
            "collectionKeys": [
              "repositories",
              "data"
            ],
            "collectionName": "repositories",
            "itemFields": [
              {
                "name": "id"
              },
              {
                "name": "node_id"
              },
              {
                "name": "name"
              },
              {
                "name": "full_name"
              },
              {
                "name": "description",
                "maxLength": 300
              },
              {
                "name": "owner",
                "kind": "contact"
              },
              {
                "name": "html_url"
              },
              {
                "name": "private"
              },
              {
                "name": "visibility"
              },
              {
                "name": "language"
              },
              {
                "name": "stargazers_count"
              },
              {
                "name": "fork"
              },
              {
                "name": "archived"
              },
              {
                "name": "open_issues_count"
              },
              {
                "name": "default_branch"
              },
              {
                "name": "updated_at"
              },
              {
                "name": "pushed_at"
              }
            ],
            "omitted": "provider-specific repository payload fields"
          }
        }
      }
    },
    {
      "id": "github__get_user",
      "name": "Get User",
      "description": "Get a GitHub user profile by username. Use this to verify repository owners, assignees, and other GitHub usernames before acting.",
      "requiresWrite": false,
      "endpoint": {
        "method": "GET",
        "url": "https://api.github.com/users/{username}",
        "params": {
          "username": {
            "type": "string",
            "in": "path",
            "description": "GitHub username/login to look up",
            "required": true
          }
        }
      }
    },
    {
      "id": "github__get_repo",
      "name": "Get Repository",
      "description": "Get details of a specific repository",
      "requiresWrite": false,
      "endpoint": {
        "method": "GET",
        "url": "https://api.github.com/repos/{owner}/{repo}",
        "params": {
          "owner": {
            "type": "string",
            "in": "path",
            "description": "Repository owner",
            "required": true
          },
          "repo": {
            "type": "string",
            "in": "path",
            "description": "Repository name",
            "required": true
          }
        }
      }
    },
    {
      "id": "github__list_prs",
      "name": "List Pull Requests",
      "description": "Get pull requests for a repository",
      "requiresWrite": false,
      "endpoint": {
        "method": "GET",
        "url": "https://api.github.com/repos/{owner}/{repo}/pulls",
        "params": {
          "owner": {
            "type": "string",
            "in": "path",
            "description": "Repository owner",
            "required": true
          },
          "repo": {
            "type": "string",
            "in": "path",
            "description": "Repository name",
            "required": true
          },
          "state": {
            "type": "string",
            "in": "query",
            "description": "State: open, closed, all",
            "default": "open"
          },
          "per_page": {
            "type": "number",
            "in": "query",
            "description": "Results per page",
            "default": 30
          },
          "page": {
            "type": "number",
            "in": "query",
            "description": "Page number for pagination"
          }
        },
        "response": {
          "historicalSummary": {
            "collectionKeys": [
              "pullRequests",
              "data"
            ],
            "collectionName": "pullRequests",
            "itemFields": [
              {
                "name": "id"
              },
              {
                "name": "node_id"
              },
              {
                "name": "number"
              },
              {
                "name": "title"
              },
              {
                "name": "body",
                "maxLength": 500
              },
              {
                "name": "state"
              },
              {
                "name": "html_url"
              },
              {
                "name": "head",
                "kind": "object"
              },
              {
                "name": "base",
                "kind": "object"
              },
              {
                "name": "labels",
                "kind": "named-array"
              },
              {
                "name": "requested_reviewers",
                "kind": "contact-array"
              },
              {
                "name": "user",
                "kind": "contact"
              },
              {
                "name": "created_at"
              },
              {
                "name": "updated_at"
              },
              {
                "name": "closed_at"
              },
              {
                "name": "merged_at"
              },
              {
                "name": "draft"
              }
            ],
            "omitted": "pull request diffs and provider-specific payload fields"
          }
        }
      }
    },
    {
      "id": "github__create_issue",
      "name": "Create Issue",
      "description": "Create a new issue in a repository",
      "requiresWrite": true,
      "endpoint": {
        "method": "POST",
        "url": "https://api.github.com/repos/{owner}/{repo}/issues",
        "params": {
          "owner": {
            "type": "string",
            "in": "path",
            "description": "Repository owner",
            "required": true
          },
          "repo": {
            "type": "string",
            "in": "path",
            "description": "Repository name",
            "required": true
          }
        },
        "body": {
          "title": {
            "type": "string",
            "description": "Issue title",
            "required": true
          },
          "body": {
            "type": "string",
            "description": "Issue body (markdown)"
          },
          "labels": {
            "type": "array",
            "description": "Label names"
          },
          "assignees": {
            "type": "array",
            "description": "Usernames to assign"
          }
        }
      }
    },
    {
      "id": "github__get_pr_diff",
      "name": "Get PR Diff",
      "description": "Get the diff for a pull request",
      "requiresWrite": false,
      "endpoint": {
        "method": "GET",
        "url": "https://api.github.com/repos/{owner}/{repo}/pulls/{pull_number}",
        "params": {
          "owner": {
            "type": "string",
            "in": "path",
            "description": "Repository owner",
            "required": true
          },
          "repo": {
            "type": "string",
            "in": "path",
            "description": "Repository name",
            "required": true
          },
          "pull_number": {
            "type": "number",
            "in": "path",
            "description": "Pull request number",
            "required": true
          },
          "Accept": {
            "type": "string",
            "in": "header",
            "description": "Response format",
            "default": "application/vnd.github.v3.diff"
          }
        }
      }
    },
    {
      "id": "github__list_issues",
      "name": "List Issues",
      "description": "List issues for a repository",
      "requiresWrite": false,
      "endpoint": {
        "type": "graphql",
        "method": "POST",
        "url": "https://api.github.com/graphql",
        "query": "query($owner: String!, $repo: String!, $first: Int, $after: String, $states: [IssueState!]) { repository(owner: $owner, name: $repo) { issues(first: $first, after: $after, states: $states, orderBy: { field: UPDATED_AT, direction: DESC }) { nodes { id number title body state url createdAt updatedAt author { login } labels(first: 10) { totalCount nodes { name } } assignees(first: 10) { totalCount nodes { login } } } pageInfo { hasNextPage endCursor } } } }",
        "params": {
          "owner": {
            "type": "string",
            "in": "body",
            "description": "Repository owner",
            "required": true
          },
          "repo": {
            "type": "string",
            "in": "body",
            "description": "Repository name",
            "required": true
          },
          "states": {
            "type": "string[]",
            "in": "body",
            "description": "Issue states to include (e.g. OPEN, CLOSED)",
            "default": [
              "OPEN"
            ]
          },
          "first": {
            "type": "number",
            "in": "body",
            "description": "Results per page",
            "default": 30
          },
          "after": {
            "type": "string",
            "in": "body",
            "description": "Pagination cursor from pageInfo.endCursor"
          }
        },
        "response": {
          "transform": "repository.issues.nodes",
          "historicalSummary": {
            "collectionKeys": [
              "issues",
              "nodes",
              "data"
            ],
            "collectionName": "issues",
            "itemFields": [
              {
                "name": "id"
              },
              {
                "name": "node_id"
              },
              {
                "name": "number"
              },
              {
                "name": "title"
              },
              {
                "name": "body",
                "maxLength": 500
              },
              {
                "name": "state"
              },
              {
                "name": "url"
              },
              {
                "name": "html_url"
              },
              {
                "name": "labels",
                "kind": "object"
              },
              {
                "name": "assignees",
                "kind": "object"
              },
              {
                "name": "author",
                "kind": "contact"
              },
              {
                "name": "user",
                "kind": "contact"
              },
              {
                "name": "createdAt"
              },
              {
                "name": "updatedAt"
              },
              {
                "name": "created_at"
              },
              {
                "name": "updated_at"
              }
            ],
            "outputFields": [
              {
                "name": "pageInfo",
                "kind": "object"
              }
            ],
            "omitted": "issue comments, timeline, and provider-specific payload fields"
          }
        }
      }
    },
    {
      "id": "github__get_issue",
      "name": "Get Issue",
      "description": "Get details of a GitHub issue",
      "requiresWrite": false,
      "endpoint": {
        "method": "GET",
        "url": "https://api.github.com/repos/{owner}/{repo}/issues/{issue_number}",
        "params": {
          "owner": {
            "type": "string",
            "in": "path",
            "description": "Repository owner",
            "required": true
          },
          "repo": {
            "type": "string",
            "in": "path",
            "description": "Repository name",
            "required": true
          },
          "issue_number": {
            "type": "number",
            "in": "path",
            "description": "Issue number",
            "required": true
          }
        },
        "response": {
          "historicalSummary": {
            "collectionKeys": [
              "issue",
              "data"
            ],
            "collectionName": "issues",
            "itemFields": [
              {
                "name": "id"
              },
              {
                "name": "node_id"
              },
              {
                "name": "number"
              },
              {
                "name": "title"
              },
              {
                "name": "body",
                "maxLength": 2000
              },
              {
                "name": "state"
              },
              {
                "name": "html_url"
              },
              {
                "name": "url"
              },
              {
                "name": "user",
                "kind": "contact"
              },
              {
                "name": "author",
                "kind": "contact"
              },
              {
                "name": "created_at"
              },
              {
                "name": "updated_at"
              },
              {
                "name": "closed_at"
              },
              {
                "name": "createdAt"
              },
              {
                "name": "updatedAt"
              }
            ],
            "singleItem": true,
