      "description": "Update, close, or reopen a GitHub issue",
      "requiresWrite": true,
      "endpoint": {
        "method": "PATCH",
        "url": "https://api.github.com/repos/{owner}/{repo}/issues/{issue_number}",
        "params": {
          "owner": {
            "type": "string",
            "in": "path",
            "description": "Repository owner",
            "required": true
          },
          "repo": {
            "type": "string",
            "in": "path",
            "description": "Repository name",
            "required": true
          },
          "issue_number": {
            "type": "number",
            "in": "path",
            "description": "Issue number",
            "required": true
          }
        },
        "body": {
          "title": {
            "type": "string",
            "description": "Updated issue title"
          },
          "body": {
            "type": "string",
            "description": "Updated issue body (markdown)"
          },
          "state": {
            "type": "string",
            "description": "Issue state: open or closed"
          },
          "labels": {
            "type": "array",
            "description": "Replacement label names"
          },
          "assignees": {
            "type": "array",
            "description": "Replacement assignee usernames"
          }
        }
      }
    },
    {
      "id": "github__add_issue_comment",
      "name": "Add Issue Comment",
      "description": "Add a comment to a GitHub issue or pull request",
      "requiresWrite": true,
      "endpoint": {
        "method": "POST",
        "url": "https://api.github.com/repos/{owner}/{repo}/issues/{issue_number}/comments",
        "params": {
          "owner": {
            "type": "string",
            "in": "path",
            "description": "Repository owner",
            "required": true
          },
          "repo": {
            "type": "string",
            "in": "path",
            "description": "Repository name",
            "required": true
          },
