  "setupGuide": {
    "title": "Gmail setup",
    "steps": [
      {
        "step": 1,
        "title": "Choose who owns the Google OAuth app",
        "description": "On hosted Veryfront, Gmail uses the Veryfront-managed Google OAuth app: connect Gmail from the project's integrations and approve the Google consent screen, no environment variables needed. Set GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET only to use your own Google OAuth app, which is required for local and self-hosted runs."
      },
      {
        "step": 2,
        "title": "Enable the Gmail API",
        "description": "In the Google Cloud project that owns your OAuth app, enable the Gmail API.",
        "url": "https://console.cloud.google.com/apis/library/gmail.googleapis.com"
      },
      {
        "step": 3,
        "title": "Configure the OAuth consent screen",
        "description": "Configure the consent screen and add the scopes this connector requests. While the app's publishing status is Testing, only the test users you list can authorize it, and Google expires their refresh tokens after 7 days, so they must reconnect weekly. Publishing an app that requests Gmail's restricted scopes to external users requires Google's OAuth app verification.",
        "docsUrl": "https://developers.google.com/workspace/gmail/api/auth/scopes"
