  "setupGuide": {
    "title": "Jira setup",
    "steps": [
      {
        "step": 1,
        "title": "Choose who owns the Atlassian OAuth app",
        "description": "On hosted Veryfront, Jira uses the Veryfront-managed Atlassian OAuth app: connect Jira from the project's integrations and approve the Atlassian consent screen, no environment variables needed. Set ATLASSIAN_CLIENT_ID and ATLASSIAN_CLIENT_SECRET only to use your own Atlassian OAuth app, which is required for local and self-hosted runs."
      },
      {
        "step": 2,
        "title": "Create an OAuth 2.0 integration",
        "description": "In the Atlassian developer console, create an OAuth 2.0 integration.",
        "url": "https://developer.atlassian.com/console/myapps/"
      },
      {
        "step": 3,
        "title": "Add the Jira API permissions",
        "description": "Under Permissions, add the Jira API and select these scopes: read:jira-work, write:jira-work, read:jira-user. offline_access is requested at authorization time so the connection can refresh its token."
      },
      {
        "step": 4,
        "title": "Add the callback URLs",
        "description": "Under Authorization, choose OAuth 2.0 (3LO). Add the redirect URI of the environment that completes the flow: https://api.veryfront.com/oauth/callback/jira for hosted Veryfront, or your app origin followed by /api/auth/jira/callback for a local or self-hosted app. Set ATLASSIAN_CLIENT_ID and ATLASSIAN_CLIENT_SECRET from the app's credentials."
      },
      {
        "step": 5,
        "title": "Share the app",
        "description": "Under Distribution, set the app to sharing so users outside your own Atlassian account can authorize it."
      },
      {
        "step": 6,
        "title": "Verify access",
        "description": "Run List Atlassian Sites (read-only) to find the site's cloud ID, then run List Projects (read-only) against that site. Neither call changes anything."
      }
    ],
    "notes": [
      "The connection requests read:jira-work, write:jira-work, read:jira-user and offline_access.",
      "If the user can reach more than one Atlassian site, set JIRA_CLOUD_ID to the target site's cloud ID from List Atlassian Sites.",
