{
  "name": "mixpanel",
  "displayName": "Mixpanel",
  "icon": "mixpanel.svg",
  "description": "Track events, analyze funnels, and understand user behavior with Mixpanel analytics",
  "auth": {
    "type": "basic",
    "usernameKey": "MIXPANEL_SERVICE_ACCOUNT_USERNAME",
    "passwordKey": "MIXPANEL_SERVICE_ACCOUNT_SECRET",
    "docsUrl": "https://developer.mixpanel.com/reference/service-accounts",
    "requiredApis": [
      {
        "name": "Mixpanel Service Accounts",
        "enableUrl": "https://mixpanel.com/settings/org#serviceaccounts"
      }
    ]
  },
  "envVars": [
    {
      "name": "MIXPANEL_SERVICE_ACCOUNT_USERNAME",
      "description": "Mixpanel service account username (HTTP Basic username for Query and Export APIs)",
      "required": true,
      "sensitive": false,
      "docsUrl": "https://developer.mixpanel.com/reference/service-accounts"
    },
    {
      "name": "MIXPANEL_SERVICE_ACCOUNT_SECRET",
      "description": "Mixpanel service account secret (HTTP Basic password for Query and Export APIs)",
      "required": true,
      "sensitive": true,
      "docsUrl": "https://developer.mixpanel.com/reference/service-accounts"
    },
    {
      "name": "MIXPANEL_PROJECT_TOKEN",
      "description": "Mixpanel Project Token for event tracking",
      "required": false,
      "sensitive": true,
      "docsUrl": "https://docs.mixpanel.com/docs/tracking/how-tos/api-credentials"
    },
    {
      "name": "MIXPANEL_API_SECRET",
      "description": "Legacy Mixpanel project API secret (deprecated by Mixpanel in favor of service accounts; only used by local file-based tools)",
      "required": false,
      "sensitive": true,
      "docsUrl": "https://developer.mixpanel.com/reference/authentication"
    },
    {
      "name": "MIXPANEL_PROJECT_ID",
      "description": "Mixpanel Project ID (found in project settings; pass it as the project_id parameter on query tools)",
      "required": false,
      "sensitive": false,
      "docsUrl": "https://docs.mixpanel.com/docs/admin/organizations-projects/manage-projects"
    },
    {
      "name": "MIXPANEL_HOST",
      "description": "Mixpanel API host without scheme: mixpanel.com (US), eu.mixpanel.com (EU), or in.mixpanel.com (India).",
